import{_ as s,o as a,c as e,a2 as i}from"./chunks/framework.DTdEDYjJ.js";const k=JSON.parse('{"title":"配置参考","description":"","frontmatter":{},"headers":[],"relativePath":"reference/configuration.md","filePath":"reference/configuration.md"}'),d={name:"reference/configuration.md"};function o(n,t,h,l,p,r){return a(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="配置参考" tabindex="-1">配置参考 <a class="header-anchor" href="#配置参考" aria-label="Permalink to &quot;配置参考&quot;">​</a></h1><p>0.10.9 的<a href="/openbot/guide/app-authorizations.html">应用授权服务</a>使用独立加密仓。服务器设置 <code>OPENBOT_KEYS_PASSPHRASE</code>，GitHub OAuth另需 <code>OPENBOT_GITHUB_CLIENT_ID</code>；Docker外部Bot入口可选 <code>OPENBOT_WITH_INTEGRATIONS=1</code>。这不迁移下方现有模型/渠道凭据，也不改变它们的保存方式。</p><p>配置保存在各自运行环境的数据目录。桌面与 Node 独立保存配置；Fleet 包不携带模型凭据或活动浏览器会话，但可以包含记忆与摘要等资料。显式导入配置包与持续的多端同步是不同流程。</p><h2 id="数据目录" tabindex="-1">数据目录 <a class="header-anchor" href="#数据目录" aria-label="Permalink to &quot;数据目录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环境</th><th>配置方式</th></tr></thead><tbody><tr><td>Mac App</td><td>默认使用应用支持目录中的 <code>openbot</code> 数据目录</td></tr><tr><td>源码开发</td><td>使用 <code>OPENBOT_USERDATA</code> 指定独立目录</td></tr><tr><td>Node CLI</td><td>使用 <code>OPENBOT_HOME</code> 或 <code>--home</code></td></tr><tr><td>Docker Node</td><td>默认挂载 <code>/var/lib/openbot</code></td></tr></tbody></table><p>升级前备份整个数据目录。回退旧版本时恢复与该版本配套的整套状态，避免混用不同代的任务与动作账本。</p><h2 id="模型连接" tabindex="-1">模型连接 <a class="header-anchor" href="#模型连接" aria-label="Permalink to &quot;模型连接&quot;">​</a></h2><p><code>config.json</code> 中的命名 API 连接使用以下主要字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td><code>id</code></td><td>连接的稳定标识，供 Bot 引用</td></tr><tr><td><code>name</code></td><td>用户可读名称</td></tr><tr><td><code>baseUrl</code></td><td>模型服务的兼容接口地址</td></tr><tr><td><code>apiKey</code></td><td>该连接的私有模型凭据</td></tr><tr><td><code>model</code></td><td>连接默认模型</td></tr></tbody></table><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;profiles&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-provider&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;我的模型服务&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;baseUrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://api.example.com/v1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;apiKey&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR_PROVIDER_KEY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR_MODEL_NAME&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;activeProfileId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-provider&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>这是字段示例，<code>example.com</code> 不提供模型服务。请在应用中配置真实服务商信息；不要把真实 Key 放进源码或公开文档。</p><h2 id="每个-bot-的执行选择" tabindex="-1">每个 Bot 的执行选择 <a class="header-anchor" href="#每个-bot-的执行选择" aria-label="Permalink to &quot;每个 Bot 的执行选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>可用值与作用</th></tr></thead><tbody><tr><td><code>id</code></td><td>Bot 的稳定 ID，节点与桌面配置需明确对应</td></tr><tr><td><code>providerId</code></td><td>引用命名 API 连接</td></tr><tr><td><code>model</code></td><td>显式模型；留空继承所选连接默认模型</td></tr><tr><td><code>harness</code></td><td><code>dsh</code>、<code>pi</code>、<code>legacy</code>；留空跟随应用默认DSH</td></tr><tr><td><code>executionLocation</code></td><td><code>local</code> 或 <code>node</code>，用于任务与屏幕</td></tr><tr><td><code>toolsEnabled</code></td><td>是否明确启用现有工具，不由模型或文档自动开启</td></tr><tr><td><code>agent</code></td><td>已绑定的 CLI/ACP 执行器配置，沿用独立路径</td></tr></tbody></table><p>工具轮次开始时固定模型、温度、地址与凭据，中途修改只影响后续轮次。缺少有效模型时明确失败，不临时换成别的模型。</p><h2 id="node-连接" tabindex="-1">Node 连接 <a class="header-anchor" href="#node-连接" aria-label="Permalink to &quot;Node 连接&quot;">​</a></h2><p>桌面保存 Node 地址与私有令牌。当前推荐地址为通过 SSH 转发后的 <code>http://127.0.0.1:14718</code>。</p><p>Node 主令牌保存在节点数据目录的 <code>node.json</code>，不是模型 API Key，也不是用户账号会话。默认启动日志不打印令牌，需要时在自己的节点终端显式执行 <code>token</code> 命令。</p><p>凭据目前保存在受权限保护的本地配置文件，而非系统钥匙串。私有目录使用0700，凭据文件使用0600；备份也需要保留对应保护。</p><h2 id="docker-运行配置" tabindex="-1">Docker 运行配置 <a class="header-anchor" href="#docker-运行配置" aria-label="Permalink to &quot;Docker 运行配置&quot;">​</a></h2><p><code>/etc/openbot/node.env</code> 指定已经校验的镜像 ID、数据目录和 Chromium 可执行文件。它不应携带模型 Key。</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">OPENBOT_IMAGE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=sha256:&lt;VERIFIED_IMAGE_ID&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">OPENBOT_DATA_DIR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/var/lib/openbot</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">OPENBOT_BROWSER_EXECUTABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/ms-playwright/chromium-1234/chrome-linux64/chrome</span></span></code></pre></div><p>完整安装、版本切换与回滚见<a href="/openbot/deployment/self-host.html">部署 Linux Node</a>。</p>`,22)])])}const E=s(d,[["render",o]]);export{k as __pageData,E as default};
